<?php
$invoices=query("SELECT i.*,c.name,(SELECT MIN(d.day) FROM biz_sales s JOIN biz_deliveries d ON d.id=s.delivery_id WHERE s.invoice_id=i.id) delivery_day,COALESCE((SELECT SUM(cents) FROM biz_payments WHERE invoice_id=i.id),0) paid FROM biz_invoices i JOIN biz_clients c ON c.id=i.client_id WHERE i.kind='direct' AND NOT EXISTS (SELECT 1 FROM biz_sales s JOIN biz_deliveries d ON d.id=s.delivery_id JOIN biz_deliveries x ON x.batch_key=d.batch_key WHERE s.invoice_id=i.id AND x.cancelled=0 AND x.sent=0) HAVING total_cents>paid ORDER BY delivery_day DESC,i.id DESC")->fetchAll(); ?>
<section class="panel"><h2>납품 완료 · 미수금 <?=count($invoices)?>건</h2><?php if(!$invoices): ?><p>수금할 납품서가 없습니다.</p><?php endif ?><?php foreach($invoices as $i):$balance=(int)$i['total_cents']-(int)$i['paid']; ?><article class="biz-document-row"><div><a href="/?page=biz-invoice&amp;id=<?=$i['id']?>"><strong><?=e($i['name'])?></strong> · RN<?=$i['id']?></a><p><?=e($i['delivery_day'])?> · 청구 <?=money((int)$i['total_cents'])?> · 입금 <?=money((int)$i['paid'])?> · 잔액 <strong><?=money($balance)?></strong></p></div><form method="post" class="biz-inline"><?=csrf()?><input type="hidden" name="action" value="biz_payment"><input type="hidden" name="return_to" value="collections"><input type="hidden" name="id" value="<?=$i['id']?>"><input type="hidden" name="request_key" value="<?=bin2hex(random_bytes(16))?>"><label>입금일<input name="day" type="date" value="<?=$today?>" required></label><label>입금액<input name="amount" type="number" min=".01" max="<?=$balance/100?>" step=".01" value="<?=number_format($balance/100,2,'.','')?>" required></label><label>입금 방법<select name="method"><option value="etransfer">eTransfer</option><option value="cash">현금</option></select></label><button class="button">입금</button></form></article><?php endforeach ?></section>
<p class="hint">위탁판매분은 ‘위탁판매 정산·수금’에서 기간 정산 후 입금을 기록합니다.</p>
